def forward(params, x, bn, training, drop_key=None):
    bn_out = []
    bn_i = 0
    x = x.reshape(-1, 3, 224, 224)
    dpkeys = (jax.random.split(drop_key, 16) if drop_key is not None else [None] * 16)
    x, _ns = conv_bn(x, params[0][0], params[0][1], params[0][2], bn[bn_i], training, stride=(2,2))
    bn_out.append(_ns); bn_i += 1
    x = jax.nn.relu(x)
    x = max_pool2d(x, 3, 2)
    x, _ne = bottleneck_block_down(params, x, 1, 1, bn, bn_i, training, dpkeys[0], 1.000000)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = bottleneck_block(params, x, 5, bn, bn_i, training, dpkeys[1], 0.996667)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = bottleneck_block(params, x, 8, bn, bn_i, training, dpkeys[2], 0.993333)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = bottleneck_block_down(params, x, 11, 2, bn, bn_i, training, dpkeys[3], 0.990000)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = bottleneck_block(params, x, 15, bn, bn_i, training, dpkeys[4], 0.986667)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = bottleneck_block(params, x, 18, bn, bn_i, training, dpkeys[5], 0.983333)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = bottleneck_block(params, x, 21, bn, bn_i, training, dpkeys[6], 0.980000)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = bottleneck_block_down(params, x, 24, 2, bn, bn_i, training, dpkeys[7], 0.976667)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = bottleneck_block(params, x, 28, bn, bn_i, training, dpkeys[8], 0.973333)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = bottleneck_block(params, x, 31, bn, bn_i, training, dpkeys[9], 0.970000)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = bottleneck_block(params, x, 34, bn, bn_i, training, dpkeys[10], 0.966667)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = bottleneck_block(params, x, 37, bn, bn_i, training, dpkeys[11], 0.963333)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = bottleneck_block(params, x, 40, bn, bn_i, training, dpkeys[12], 0.960000)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = bottleneck_block_down(params, x, 43, 2, bn, bn_i, training, dpkeys[13], 0.956667)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = bottleneck_block(params, x, 47, bn, bn_i, training, dpkeys[14], 0.953333)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = bottleneck_block(params, x, 50, bn, bn_i, training, dpkeys[15], 0.950000)
    bn_out.extend(_ne); bn_i += len(_ne)
    x = global_avg_pool(x)
    x = mm(x, params[53][0].T) + params[53][1]
    return x, bn_out

def loss_fn(params, bn, x, y, drop_key=None):
    logits, _new_bn = forward(params, x, bn, True, drop_key)
    # BCE-with-logits over multi-hot [B,NC] targets (RSB-A2); each class an
    # independent sigmoid. y.ndim is static at trace time, so this is jit-safe.
    if y.ndim == 1:
        tgt = jax.nn.one_hot(y, 1000)
    else:
        tgt = y
    # stable log-sigmoid via softplus: -log(sig(z))=softplus(-z), -log(1-sig(z))=softplus(z)
    bce = tgt * jax.nn.softplus(-logits) + (1.0 - tgt) * jax.nn.softplus(logits)
    return jnp.mean(bce), _new_bn

def augment_batch(x, rng):
    """Random crop (numpy, CPU): pad 224→252, crop back to 224x224."""
    x = x.reshape(-1, 3, 224, 224)
    x = np.pad(x, ((0,0), (0,0), (14,14), (14,14)))
    top = rng.randint(0, 29)
    left = rng.randint(0, 29)
    x = x[:, :, top:top+224, left:left+224]
    return x.reshape(x.shape[0], -1)

# ═══════════════════════════════════════════════════════════════════════
#  Training  (LAMB + cosine LR)
# ═══════════════════════════════════════════════════════════════════════

LR = 0.005000
BETA1 = 0.9
BETA2 = 0.999
EPS = 1e-6
WD = 0.020000
_WD_POS_SHAPE = None
def _wd_mask(params):
    # timm no_weight_decay: no decay on 1-D params (biases, LayerNorm γ/β,
    # CLS token) or the positional embedding (2-D but must not be decayed).
    def _leaf(p):
        if p.ndim <= 1: return jnp.zeros_like(p)
        if p.shape == _WD_POS_SHAPE: return jnp.zeros_like(p)
        return jnp.ones_like(p)
    return jax.tree.map(_leaf, params)

@jit
def train_step(params, opt_state, bn, x, y, lr, drop_key=None):
    (loss, _new_bn), grads = value_and_grad(loss_fn, has_aux=True)(params, bn, x, y, drop_key)
    gn = jnp.sqrt(sum(jnp.sum(g * g) for g in jax.tree.leaves(grads)))
    grads = jax.tree.map(lambda g: g * jnp.minimum(1.0, 1.000000 / (gn + 1e-6)), grads)
    m, v, t = opt_state
    t = t + 1
    m = jax.tree.map(lambda mi, g: BETA1 * mi + (1 - BETA1) * g, m, grads)
    v = jax.tree.map(lambda vi, g: BETA2 * vi + (1 - BETA2) * g * g, v, grads)
    mc = jax.tree.map(lambda mi: mi / (1 - BETA1 ** t), m)
    vc = jax.tree.map(lambda vi: vi / (1 - BETA2 ** t), v)
    def _lamb(p, mi, vi, msk):
        r = mi / (jnp.sqrt(vi) + EPS) + WD * msk * p
        wn = jnp.sqrt(jnp.sum(p * p)); rn = jnp.sqrt(jnp.sum(r * r))
        trust = jnp.where(wn > 0, jnp.where(rn > 0, wn / rn, 1.0), 1.0)
        trust = jnp.where(msk > 0, trust, 1.0)   # timm: no_weight_decay group is NOT adapted
        return p - lr * trust * r
    params = jax.tree.map(_lamb, params, mc, vc, WD_MASK)
    return params, (m, v, t), _new_bn, loss

EMA_DECAY = 0.999900
# Warmup-corrected decay, matching TF's tf.train.ExponentialMovingAverage(decay,
# num_updates) — the EMA this net family (MobileNet/EfficientNet, TF lineage) is
# defined against. Without it the shadow starts AT THE RANDOM INIT and decays that
# init away only as decay^t, so a run shorter than ~10 time constants evaluates a
# weighted average of init and trained weights. Those two are not linearly
# connected (there is a loss barrier between them), so the result is not merely
# degraded — it sits at chance.
#
# Measured on MNv4-Conv-M 100ep (2026-07-31): decay 0.9999 = tau 10k steps, but
# gradAccum 8 leaves only 312 optimizer steps/epoch = 31.2k total = 3.1 tau. At
# epoch 66 the shadow still held 12.8% init and scored 0.00% top-1, while the LIVE
# weights scored 70.48% on full 50k. Eval and .bin checkpoints both read the EMA,
# so the run looked like a total failure when only the shadow was broken.
#
# min(decay, (1+t)/(10+t)) ramps from 0.09 at t=0, so the shadow tracks the live
# weights from the first step and reaches the nominal decay once t >> 10. Long runs
# (ENet-B0 350ep = 175 tau) are unaffected either way; short/grad-accum tiers need it.
@jit
def ema_update(ema, params, step):
    d = jnp.minimum(EMA_DECAY, (1.0 + step) / (10.0 + step))
    return jax.tree.map(lambda e, p: d * e + (1.0 - d) * p, ema, params)

@jit
def _mixup(x, y, key):
    lam = jax.random.beta(key, 0.100000, 0.100000)
    y1 = jax.nn.one_hot(y, 1000)
    xm = lam * x + (1.0 - lam) * jnp.flip(x, 0)
    ym = lam * y1 + (1.0 - lam) * jnp.flip(y1, 0)
    return xm, ym

@jit
def _cutmix(x, y, key):
    B = x.shape[0]
    k1, k2, k3 = jax.random.split(key, 3)
    lam = jax.random.beta(k1, 1.000000, 1.000000)
    x4 = x.reshape(B, 3, 224, 224)
    cut = jnp.sqrt(1.0 - lam)
    cw = (cut * 224).astype(jnp.int32); ch = (cut * 224).astype(jnp.int32)
    cx = jax.random.randint(k2, (), 0, 224); cy = jax.random.randint(k3, (), 0, 224)
    x1 = jnp.clip(cx - cw // 2, 0, 224); x2 = jnp.clip(cx + cw // 2, 0, 224)
    y1c = jnp.clip(cy - ch // 2, 0, 224); y2c = jnp.clip(cy + ch // 2, 0, 224)
    mx = (jnp.arange(224) >= x1) & (jnp.arange(224) < x2)
    my = (jnp.arange(224) >= y1c) & (jnp.arange(224) < y2c)
    mask = (my[:, None] & mx[None, :]).astype(x.dtype)
    x4m = x4 * (1.0 - mask) + jnp.flip(x4, 0) * mask
    lam_adj = 1.0 - jnp.sum(mask) / (224 * 224)
    y1h = jax.nn.one_hot(y, 1000)
    ym = lam_adj * y1h + (1.0 - lam_adj) * jnp.flip(y1h, 0)
    return x4m.reshape(B, -1), ym

@jit
def eval_batch(params, bn, x, y, take):
    logits, _ = forward(params, x, bn, False)
    keep = jnp.arange(logits.shape[0]) < take
    preds = jnp.argmax(logits, axis=-1)
    log_probs = jax.nn.log_softmax(logits, axis=-1)
    loss = -(jnp.sum(jnp.sum(log_probs * jax.nn.one_hot(y, 1000), axis=-1) * keep) / jnp.maximum(take, 1))
    correct1 = jnp.sum((preds == y) & keep)
    # top-5: jax.lax.top_k's indices are broken on ROCm/gfx1100 (garbage on
    # device, HIP error to host), so rank the true class instead — top-5 is
    # correct iff fewer than 5 classes have a strictly-greater logit.
    true_logit = jnp.take_along_axis(logits, y[:, None], axis=1)
    correct5 = jnp.sum((jnp.sum(logits > true_logit, axis=1) < 5) & keep)
    return correct1, correct5, loss

def evaluate(params, images, labels, batch_size=512):
    batch_size = (batch_size // n_devices) * n_devices or n_devices
    _p = np.random.default_rng(12345).permutation(len(labels))
    images, labels = images[_p], labels[_p]
    correct1 = 0
    correct5 = 0
    total_loss = 0.0
    n_batches = 0
    for i in range(0, len(images), batch_size):
        xb, yb = images[i:i+batch_size], labels[i:i+batch_size]
        take = len(yb)
        if take < batch_size:
            pad = batch_size - take
            xb = np.concatenate([xb, images[:pad]], axis=0)
            yb = np.concatenate([yb, labels[:pad]], axis=0)
        c1, c5, l = eval_batch(params,
            jax.device_put(xb, data_sharding),
            jax.device_put(yb, data_sharding),
            take)
        correct1 += int(c1)
        correct5 += int(c5)
        total_loss += float(l)
        n_batches += 1
    evaluated = len(labels)
    return correct1, correct5, evaluated, total_loss / max(n_batches, 1)

# ═══════════════════════════════════════════════════════════════════════
#  Main (ImageNet streaming variant)
# ═══════════════════════════════════════════════════════════════════════

def save_train_state(path, state, step):
    """Full suspend/resume: flatten (params, opt_state[, ema]) + global step into
    one .npz so a segmented run (train N epochs, stop, resume) continues bit-for-
    bit — Adam m/v and the EMA shadow survive, not just the weights. Structure is
    rebuilt at load from a fresh template, so this is optimizer-agnostic."""
    leaves = jax.tree.leaves(state)
    arrs = {f'l{i}': np.asarray(x) for i, x in enumerate(leaves)}
    arrs['step'] = np.int64(step)
    tmp = path + '.tmp'
    with open(tmp, 'wb') as _f:  # pass a file object so np.savez won't append .npz
        np.savez(_f, **arrs)
    os.replace(tmp, path)        # atomic rename: a crash mid-save can't corrupt `path`
    print(f'  saved full train state -> {path} ({len(leaves)} arrays, step={step})')

def _prune_state_ckpts(base):
    """Keep only the newest LEAN_MLIR_KEEP_STATE (default 3) <base>_e{N}.state.npz
    files. Each is ~4x the weights, so an every-epoch run would otherwise pile up
    tens of GB; only resumes from the newest are ever needed."""
    import glob
    keep = int(os.environ.get('LEAN_MLIR_KEEP_STATE', '3'))
    if keep <= 0:
        return
    paths = glob.glob(f'{base}_e*.state.npz')
    paths.sort(key=lambda p: int(p.rsplit('_e', 1)[1].split('.state.npz')[0]))
    for _old in paths[:-keep]:
        try:
            os.remove(_old)
        except OSError:
            pass

def _prune_bin_ckpts(base):
    """Keep only the newest LEAN_MLIR_KEEP_BIN (default 0 = keep everything)
    <base>_e{N}.bin weight files. Off by default so existing runs are unchanged;
    set it for the big nets, where an every-epoch 300-epoch run would otherwise
    write ~100 GB of weights (ViT-B and ConvNeXt-B are ~340 MB per .bin)."""
    import glob
    keep = int(os.environ.get('LEAN_MLIR_KEEP_BIN', '0'))
    if keep <= 0:
        return
    paths = glob.glob(f'{base}_e*.bin')
    paths.sort(key=lambda p: int(p.rsplit('_e', 1)[1].split('.bin')[0]))
    for _old in paths[:-keep]:
        try:
            os.remove(_old)
        except OSError:
            pass

def load_train_state(path, template):
    d = np.load(path)
    n = len(jax.tree.leaves(template))
    leaves = [jnp.asarray(d[f'l{i}']) for i in range(n)]
    return jax.tree.unflatten(jax.tree.structure(template), leaves), int(d['step'])

if __name__ == "__main__":
    print("ResNet-50 (ImageNet) · Lean 4 → JAX")
    print("  " + "Conv(3→64,7x7/2)+BN → Pool(3x3) → BN3(64→256,s1) → BN4(256→512,s2) → BN6(512→1024,s2) → BN3(1024→2048,s2) → GAP → 2048→1000")
    print()

    data_dir = "data/imagenet"   # not used for tfds (TFDS_DATA_DIR env var is)
    print("ImageNet (1000-class) — tfds streaming pipeline")
    train_examples = 1281167
    val_examples   = 50000

    BATCH_SIZE = (2048 // n_devices) * n_devices or n_devices
    EPOCHS = 300
    LR = 0.005000
    steps_per_epoch = train_examples // BATCH_SIZE
    total_steps = steps_per_epoch * EPOCHS
    print("lr=0.005000  batch_size=" + str(BATCH_SIZE) +
          " (" + str(n_devices) + " devices x " + str(BATCH_SIZE // n_devices) + ")" +
          "  epochs=" + str(EPOCHS) + "  params=25557032")
    print("steps_per_epoch=" + str(steps_per_epoch) + "  total_steps=" + str(total_steps))
    print("backend=" + str(jax.default_backend()) + "  devices=" + str(jax.devices()))
    print("repeated-aug=3x (RSB / timm RASampler approximation: stream-level repeat+shuffle)")
    print("Starting training...")

    _init_load = os.environ.get('LEAN_MLIR_INIT_LOAD')
    if _init_load:
        print(f'Loading phase-3 init from {_init_load}')
        params = init_params_from_file(_init_load)
    else:
        params = init_params(random.PRNGKey(314159))
    params = jax.device_put(params, replicated_sharding)
    WD_MASK = _wd_mask(params)  # timm no_weight_decay mask (built once; shape-only, resume-safe)
    opt_m = jax.tree.map(jnp.zeros_like, params)
    opt_v = jax.tree.map(jnp.zeros_like, params)
    opt_state = (opt_m, opt_v, jnp.float32(0))
    bn_state = init_bn_state()  # running BN mean/var (gap A), threaded through train/eval

    # Trace emission (opt-in; matches phase-3 format).
    _trace_path = os.environ.get('LEAN_MLIR_TRACE_OUT')
    _trace_f = open(_trace_path, 'w') if _trace_path else None
    if _trace_f:
        _hdr = {
            'kind': 'header', 'phase': 'phase2',
            'netspec_name': "ResNet-50 (ImageNet)",
            'config': {
                'lr': 0.005000, 'batch_size': 2048, 'epochs': 300,
                'use_adam': False,
                'weight_decay': 0.020000,
                'cosine': True,
                'warmup_epochs': 5,
                'augment': True,
                'label_smoothing': 0.000000,
                'seed': 314159,
            },
            'total_params': 25557032,
            'dataset': 'imagenet',
            'emitter_version': '1',
        }
        _trace_f.write(json.dumps(_hdr) + '\n')

    train_iter = prefetch_to_device(
        iter(build_imagenet_iter('train', BATCH_SIZE,
                                 training=True,
                                 augment=True)),
        data_sharding)
    # LEAN_MLIR_START_STEP lets a resumed run continue the cosine LR schedule
    # from where it left off (instead of restarting from warmup which would
    # destabilize a partly-trained model). Set to the global_step the prior
    # checkpoint corresponds to — e.g. 50040 for resume-from-epoch-10 with
    # steps_per_epoch=5004. The matching epoch counter is derived so the
    # per-epoch log line keeps reporting the absolute epoch number.
    _global_step = int(os.environ.get('LEAN_MLIR_START_STEP', '0'))
    _start_epoch = _global_step // steps_per_epoch
    if _global_step > 0:
        print(f'Resuming at global_step={_global_step} (= epoch {_start_epoch + 1}/{EPOCHS}); LR schedule continues from there')
    t0 = time.time()
    ema_params = params  # EMA shadow starts at the (fresh or resumed) weights
    ema_bn = bn_state  # EMA shadow of the BN running buffers — eval pairs EMA weights with EMA-lagged BN stats, avoiding the weights/stats mismatch that blows up early eval
    _drop_base = random.PRNGKey(314159 + 1)  # stochastic-depth + dropout RNG stream
    _resume = os.environ.get('LEAN_MLIR_RESUME')
    if _resume:
        _rstate, _global_step = load_train_state(_resume, (params, opt_state, ema_params, ema_bn, bn_state))
        (params, opt_state, ema_params, ema_bn, bn_state) = jax.device_put(_rstate, replicated_sharding)
        _start_epoch = _global_step // steps_per_epoch
        print(f'Resumed full train state from {_resume}: step={_global_step} (epoch {_start_epoch + 1}/{EPOCHS})')
    for epoch in range(_start_epoch, EPOCHS):
        # Per-step LR (computed inside the inner loop below)
        pass
        ep_t0 = time.time()
        epoch_loss = 0.0
        n_batches = 0
        for _ in range(steps_per_epoch):
            x, y = next(train_iter)
            # Per-step LR (warmup → cosine)
            warmup_steps = steps_per_epoch * 5
            if _global_step < warmup_steps:
                lr = jnp.float32(LR * (_global_step + 1) / warmup_steps)
            else:
                prog = (_global_step - warmup_steps) / max(total_steps - warmup_steps, 1)
                lr = jnp.float32(LR * 0.5 * (1 + np.cos(np.pi * min(prog, 1.0))))
            if _global_step % 2 == 0:
                x, y = _mixup(x, y, jax.random.fold_in(jax.random.PRNGKey(314159), _global_step))
            else:
                x, y = _cutmix(x, y, jax.random.fold_in(jax.random.PRNGKey(314159), _global_step))
            params, opt_state, bn_state, loss = train_step(params, opt_state, bn_state, x, y, lr, jax.random.fold_in(_drop_base, _global_step))
            epoch_loss += loss  # jax scalar: defer the device sync to epoch end
            n_batches += 1
            ema_params = ema_update(ema_params, params, _global_step)
            ema_bn = ema_update(ema_bn, bn_state, _global_step)
            _global_step += 1
            if _trace_f:
                _trace_f.write(json.dumps({
                    'kind': 'step', 'step': _global_step, 'epoch': epoch,
                    'loss': float(loss), 'lr': float(lr),
                }) + '\n')
            if _global_step % 100 == 0:
                print("  step " + str(_global_step) + "/" + str(total_steps) +
                      "  loss=" + str(round(float(loss), 4)) +
                      "  lr=" + str(round(float(lr), 5)) +
                      "  (" + str(round((time.time()-t0)/_global_step*1000, 0)) + "ms/step avg)")

        train_secs = time.time() - ep_t0  # train-only wall time (measured before validation)
        # Validation pass: rebuild iterator each epoch (non-repeating).
        print("  Running validation ...")
        ev_t0 = time.time()
        v_iter = prefetch_to_device(
            iter(build_imagenet_iter('validation', BATCH_SIZE, training=False, augment=False)),
            data_sharding)
        correct1 = 0
        correct5 = 0
        total = 0
        total_eval_loss = 0.0
        v_batches = 0
        for x, y in v_iter:
            c1, c5, l = eval_batch(ema_params, ema_bn, x, y, len(y))
            correct1 += int(c1)
            correct5 += int(c5)
            total   += y.shape[0]
            total_eval_loss += float(l)
            v_batches += 1
        acc1 = correct1 / max(total, 1)
        acc5 = correct5 / max(total, 1)
        print("[Epoch " + str(epoch+1) + "] lr=" + str(round(float(lr), 6)) +
              " loss(train_avg)=" + str(round(float(epoch_loss) / max(n_batches,1), 4)) +
              " val_top1=" + str(correct1) + "/" + str(total) +
              " (" + str(round(acc1, 4)) + ")" +
              " val_top5=" + str(round(acc5, 4)) +
              " val_loss=" + str(round(total_eval_loss/max(v_batches,1), 4)) +
              "  [" + str(round(train_secs, 1)) + "s train, " +
              str(round(time.time()-ev_t0, 1)) + "s val]")

        # Per-N-epoch checkpoint. LEAN_MLIR_PARAMS_OUT sets the base path;
        # writes <base>_e{N}.bin every LEAN_MLIR_CKPT_EVERY epochs (default 10)
        # plus a final <base>.bin. Matches the phase-3 trainer's per-epoch
        # save behavior so downstream bootstrap (YOLOv1) can pick up an
        # intermediate checkpoint without waiting for full training.
        _ckpt_base = os.environ.get('LEAN_MLIR_PARAMS_OUT')
        _ckpt_every = int(os.environ.get('LEAN_MLIR_CKPT_EVERY', '10'))
        if _ckpt_base and _ckpt_every > 0 and (epoch + 1) % _ckpt_every == 0:
            _ckpt_path = f'{_ckpt_base}_e{epoch+1}.bin'
            params_to_file(ema_params, _ckpt_path)
            save_train_state(f'{_ckpt_base}_e{epoch+1}.state.npz', (params, opt_state, ema_params, ema_bn, bn_state), _global_step)
            _prune_state_ckpts(_ckpt_base)
            _prune_bin_ckpts(_ckpt_base)

    # Final save (always, if LEAN_MLIR_PARAMS_OUT was set).
    _ckpt_base = os.environ.get('LEAN_MLIR_PARAMS_OUT')
    if _ckpt_base:
        params_to_file(ema_params, f'{_ckpt_base}.bin')
        save_train_state(f'{_ckpt_base}.state.npz', (params, opt_state, ema_params, ema_bn, bn_state), _global_step)

    print("")
    print("Done. Total time: " + str(round(time.time() - t0, 1)) + "s")
    if _trace_f: _trace_f.close()
